  if(worldState.recentSwitch){var rs=worldState.recentSwitch,_kdSw=(typeof kindDef==="function")?kindDef():null;/* #6: the kind may supply the wording (the village's encounter beat); adventure keeps the literal below byte-identical */if(_kdSw&&_kdSw.switchPovBlock)switchBlock=_kdSw.switchPovBlock(rs);else switchBlock="*** CONTROL RECENTLY SWITCHED — READ CAREFULLY ***
The player now plays "+rs.to+". Second-person narration ('you'/'your') refers to "+rs.to+" and ONLY "+rs.to+". "+rs.from+" is now a non-player companion in the party — describe "+rs.from+" in the third person by name, never as 'you'. The conversation history above was written while "+rs.from+" was the player character; do NOT let that mislead you into addressing "+rs.from+" as the protagonist. The protagonist is now "+rs.to+".

